        protected override void RunAsync(IStageHost<ProcedureId, ProcedureArgs> m, in ProcedureArgs req, CancellationToken ct)
        {
            // 已取票排队的合法票据：先原子验活并消费队列，拒绝时零连接、不回写流程。
            RoomFlowOperation operation = req.RoomOperation;
